/* Keep the stock Quit item and remove the Xbox Live menu entry. */
if (edi != 0) {
    ebx = 0x2F8F24; /* "online" */
    g_ebp = ebp;
    g_seh_ebp = ebp;
    PUSH32(esp, 0x0007C5F5u); RECOMP_ABI_CALL(0x001924C0u, sub_001924C0);
}

/* The main menu initializes and refreshes this shared online-status field. */
if (MEM32(esp + 0x8C) == 0x0007C6ECu || MEM32(esp + 0x8C) == 0x0007CCA5u) {
    static const wchar_t version[] = L"ReSqueezed v0.1a";
    memcpy((void *)(g_xbox_mem_offset + esp + 0xC), version, sizeof version);
}

if (getenv("RECOMP_JUICED_VIDEO_TRACE")) {
    const uint32_t movie = MEM32(esi + 0x30);
    static RECOMP_TLS uint32_t last_frame;
    static RECOMP_TLS uint32_t copies;
    uint32_t frame = MEM32(movie + 0xC);
    if (++copies <= 6 || (frame != last_frame && frame % 30 == 0))
        fprintf(stderr, "[Juiced video] copy %u frame %u/%u\n", copies, frame, MEM32(movie + 8));
    last_frame = frame;
}

if (getenv("JUICED_SAVE_TRACE"))
    fprintf(stderr, "[SAVE] payload write returned %u, wrote %u of %u bytes\n",
            eax, MEM32(esp + 0x64), ebp);

if (juiced_native_widescreen && MEM32(ecx + 0x178) == 0) {
    /* Preserve the original vertical field of view. The widescreen camera
     * uses a 9:16 vertical-to-horizontal aspect instead of 3:4. */
    fp_top() = 2.0 * atan(tan(fp_top() * 0.5) * (4.0 / 3.0));
} else {
    fp_top() = RECOMP_FP_PC(fp_top() * MEMF(0x313634));
}

float vertical_aspect = MEMF(ecx + 0xC0);
if (juiced_native_widescreen && vertical_aspect == 0.75f)
    vertical_aspect = 0.5625f;
fp_top() = RECOMP_FP_PC(fp_top() * vertical_aspect);

extern int juiced_native_widescreen;
if (juiced_native_widescreen && MEM32(ecx + 0x178) == 0)
    fp_top() = 2.0 * atan(tan(fp_top() * 0.5) * (3.0 / 4.0));
else
    fp_top() = RECOMP_FP_PC(fp_top() * MEMF(0x3134D4));

/* "yes" on the main-menu Quit dialog exits through the runtime hooks. */
if (quit_confirmation && esi == 0x32F04C) {
    quit_confirmation = 0;
    xbox_HalInitiateShutdown();
}

/* Bink's Xbox YUY2 blitter requires MMX. Keep that guest capability
   visible to this probe when the runtime masks it for other libraries. */
edx |= 0x00800000u;
